CREATE TABLE demo_runs(id uuid PRIMARY KEY, scenario_version text NOT NULL DEFAULT 'synthetic-v1', seed bigint NOT NULL DEFAULT 42, manifest_hash text, started_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sources(id uuid PRIMARY KEY, logical_name text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'healthy', last_error_code text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE file_instances(id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources, device bigint NOT NULL, inode bigint NOT NULL, generation int NOT NULL DEFAULT 0, prefix_hash text NOT NULL, prefix_len int NOT NULL, current_path text NOT NULL, retired_at timestamptz, UNIQUE(source_id,device,inode,generation));
CREATE TABLE source_cursors(file_instance_id uuid PRIMARY KEY REFERENCES file_instances, committed_offset bigint NOT NULL CHECK(committed_offset>=0), last_size bigint NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES demo_runs, external_event_id uuid NOT NULL, ingest_seq bigint GENERATED ALWAYS AS IDENTITY UNIQUE, source_id uuid NOT NULL REFERENCES sources, file_instance_id uuid NOT NULL REFERENCES file_instances, generation int NOT NULL, byte_start bigint NOT NULL, byte_end bigint NOT NULL, line_hash text NOT NULL, event_time timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT clock_timestamp(), source text NOT NULL, event_type text NOT NULL, level text NOT NULL, src_ip text, user_alias text, service text, message text NOT NULL, schema_version int NOT NULL CHECK(schema_version=1), UNIQUE(run_id,external_event_id), UNIQUE(file_instance_id,generation,byte_start));
CREATE INDEX events_run_seq ON events(run_id,ingest_seq);
CREATE INDEX events_type_time ON events(event_type,ingested_at);
CREATE INDEX events_source_seq ON events(source_id,ingest_seq);
CREATE INDEX events_service_time ON events(service,ingested_at);
CREATE TABLE ingestion_errors(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources, file_instance_id uuid REFERENCES file_instances, byte_start bigint NOT NULL, byte_end bigint NOT NULL, reason text NOT NULL, content_hash text NOT NULL, observed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(file_instance_id,byte_start,reason));
CREATE TABLE detection_work(event_id uuid PRIMARY KEY REFERENCES events, ingest_seq bigint UNIQUE NOT NULL, state text NOT NULL DEFAULT 'pending', lease_until timestamptz, attempts int NOT NULL DEFAULT 0);
CREATE TABLE detection_checkpoints(source_id uuid PRIMARY KEY REFERENCES sources, last_ingest_seq bigint NOT NULL, rule_set_version int NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rule_versions(rule_id text NOT NULL, version int NOT NULL, definition jsonb NOT NULL, definition_hash text NOT NULL, PRIMARY KEY(rule_id,version));
CREATE TABLE incidents(id uuid PRIMARY KEY, incident_key text UNIQUE NOT NULL, run_id uuid NOT NULL REFERENCES demo_runs, rule_id text NOT NULL, rule_version int NOT NULL, group_key jsonb NOT NULL, severity text NOT NULL CHECK(severity IN ('low','medium','high','critical')), title text NOT NULL, opened_at timestamptz NOT NULL, last_match_at timestamptz NOT NULL, evidence_version int NOT NULL DEFAULT 1, report_version int NOT NULL DEFAULT 1, deterministic_reason jsonb NOT NULL, pending_since timestamptz, eligible_at timestamptz, last_sent_at timestamptz, analyzed_version int NOT NULL DEFAULT 0, FOREIGN KEY(rule_id,rule_version) REFERENCES rule_versions);
CREATE INDEX incidents_opened ON incidents(opened_at DESC,id DESC);
CREATE INDEX incidents_severity ON incidents(severity,opened_at DESC);
CREATE TABLE incident_events(incident_id uuid NOT NULL REFERENCES incidents, event_id uuid NOT NULL REFERENCES events, role text NOT NULL DEFAULT 'match', added_version int NOT NULL DEFAULT 1, added_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(incident_id,event_id));
CREATE TABLE incident_relations(from_id uuid NOT NULL REFERENCES incidents, to_id uuid NOT NULL REFERENCES incidents, relation text NOT NULL, PRIMARY KEY(from_id,to_id,relation));
CREATE TABLE outbox_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, kind text NOT NULL, aggregate_id uuid, aggregate_version int NOT NULL DEFAULT 1, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_time ON outbox_events(created_at);
CREATE TABLE app_settings(key text PRIMARY KEY, value jsonb NOT NULL, version int NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_documents(id uuid PRIMARY KEY, title text NOT NULL, kind text NOT NULL CHECK(kind IN ('guide','decision_rule','rule_explanation')), source text NOT NULL, license text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_revisions(document_id uuid NOT NULL REFERENCES knowledge_documents, revision int NOT NULL, text text NOT NULL CHECK(octet_length(text)<=32768), hash text NOT NULL, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','indexing','ready','failed')), metadata jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(document_id,revision));
CREATE TABLE policy_sets(id uuid PRIMARY KEY, policies jsonb NOT NULL, hash text NOT NULL);
CREATE TABLE corpus_versions(id uuid PRIMARY KEY, policy_set_id uuid NOT NULL REFERENCES policy_sets, embedding_model_revision text NOT NULL, dimension int NOT NULL CHECK(dimension=384), state text NOT NULL CHECK(state IN ('building','ready','failed')), reason text, idempotency_key uuid UNIQUE NOT NULL, manifest_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_build ON corpus_versions((state)) WHERE state='building';
CREATE TABLE corpus_members(corpus_id uuid NOT NULL REFERENCES corpus_versions, document_id uuid NOT NULL, revision int NOT NULL, PRIMARY KEY(corpus_id,document_id), FOREIGN KEY(document_id,revision) REFERENCES knowledge_revisions);
CREATE TABLE knowledge_chunks(id uuid PRIMARY KEY, document_id uuid NOT NULL, revision int NOT NULL, ordinal int NOT NULL, text text NOT NULL, hash text NOT NULL, token_count int NOT NULL CHECK(token_count<=400), UNIQUE(document_id,revision,ordinal), FOREIGN KEY(document_id,revision) REFERENCES knowledge_revisions);
CREATE TABLE knowledge_embeddings(corpus_id uuid NOT NULL REFERENCES corpus_versions, chunk_id uuid NOT NULL REFERENCES knowledge_chunks, embedding vector(384) NOT NULL, model_revision text NOT NULL, PRIMARY KEY(corpus_id,chunk_id));
CREATE TABLE knowledge_state(singleton bool PRIMARY KEY DEFAULT true CHECK(singleton), active_corpus_id uuid NOT NULL REFERENCES corpus_versions, active_policy_version uuid NOT NULL REFERENCES policy_sets, version int NOT NULL DEFAULT 1);
CREATE TABLE decision_policies(id uuid NOT NULL, revision int NOT NULL, document_id uuid NOT NULL, scope text NOT NULL, definition jsonb NOT NULL, PRIMARY KEY(id,revision), FOREIGN KEY(document_id,revision) REFERENCES knowledge_revisions);
CREATE TABLE provider_profiles(id uuid NOT NULL, version int NOT NULL, profile jsonb NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE provider_credentials(profile_id uuid PRIMARY KEY, ciphertext bytea NOT NULL, nonce bytea NOT NULL);
CREATE TABLE tariffs(id uuid PRIMARY KEY, provider text NOT NULL, model text NOT NULL, input_rate numeric(18,8) NOT NULL, output_rate numeric(18,8) NOT NULL, verified_at timestamptz NOT NULL, source_url text NOT NULL);
CREATE TABLE budget_accounts(scope text NOT NULL, scope_key text NOT NULL, limit_units bigint NOT NULL CHECK(limit_units>=0), spent_units bigint NOT NULL DEFAULT 0 CHECK(spent_units>=0), reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units>=0), PRIMARY KEY(scope,scope_key));
CREATE TABLE conversations(id uuid PRIMARY KEY, incident_id uuid UNIQUE NOT NULL REFERENCES incidents, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations, ordinal bigint NOT NULL, role text NOT NULL CHECK(role IN ('user','assistant')), content jsonb NOT NULL, state text NOT NULL, evidence_version int NOT NULL, request_id uuid NOT NULL, idempotency_key uuid, payload_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(conversation_id,ordinal));
CREATE UNIQUE INDEX turn_idempotency ON messages(conversation_id,idempotency_key) WHERE role='user';
CREATE TABLE analysis_jobs(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('analysis','chat')), incident_id uuid NOT NULL REFERENCES incidents, message_id uuid UNIQUE REFERENCES messages, evidence_version int NOT NULL, provider_profile_version int NOT NULL, provider text NOT NULL, model text NOT NULL, prompt_version int NOT NULL DEFAULT 1, redaction_version int NOT NULL DEFAULT 1, corpus_version uuid REFERENCES corpus_versions, policy_version uuid REFERENCES policy_sets, snapshot_hash text NOT NULL, snapshot jsonb NOT NULL, state text NOT NULL, reason text, eligible_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX analysis_dedupe ON analysis_jobs(incident_id,evidence_version,provider_profile_version,corpus_version,policy_version) WHERE kind='analysis';
CREATE INDEX jobs_state ON analysis_jobs(state,eligible_at);
CREATE TABLE analysis_attempts(id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES analysis_jobs, ordinal int NOT NULL DEFAULT 1, state text NOT NULL, sent_at timestamptz, finished_at timestamptz, reserved_units bigint NOT NULL, accounted_units bigint NOT NULL DEFAULT 0, input_tokens int, output_tokens int, usage_estimated bool NOT NULL DEFAULT false, error_code text, UNIQUE(job_id,ordinal));
CREATE TABLE budget_reservations(attempt_id uuid NOT NULL REFERENCES analysis_attempts, account_scope text NOT NULL, account_key text NOT NULL, amount_units bigint NOT NULL, state text NOT NULL, PRIMARY KEY(attempt_id,account_scope,account_key), FOREIGN KEY(account_scope,account_key) REFERENCES budget_accounts);
CREATE TABLE analyses(id uuid PRIMARY KEY, job_id uuid UNIQUE NOT NULL REFERENCES analysis_jobs, origin text NOT NULL CHECK(origin IN ('mock','live','cache')), cached_from_id uuid REFERENCES analyses, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE retrieval_snapshots(id uuid PRIMARY KEY, job_id uuid UNIQUE NOT NULL REFERENCES analysis_jobs, corpus_id uuid NOT NULL REFERENCES corpus_versions, policy_set_id uuid NOT NULL REFERENCES policy_sets, query text NOT NULL, chunks jsonb NOT NULL, omitted_count int NOT NULL);
CREATE TABLE admin_sessions(token_hash text PRIMARY KEY, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE admin_requests(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
